// IL-level view of boxing -- what the compiler actually emits
// C#:
object o = 123;
int i = (int)o;

// Roughly equivalent IL:
//   ldc.i4.s   123
//   box        [mscorlib]System.Int32     <- heap allocation happens HERE
//   stloc.0
//   ldloc.0
//   unbox.any  [mscorlib]System.Int32     <- type-check + copy back out

// Span<T> -- conceptually just { void* pointer; int length; }
Span<byte> largeArraySlice = new Span<byte>(largeArray, offset: 1000, length: 500);
// No new array allocated -- this is two machine words pointing into largeArray

// readonly struct -- lets the JIT skip defensive copies
public readonly struct Point3D
{
    public readonly double X, Y, Z;
    public Point3D(double x, double y, double z) { X = x; Y = y; Z = z; }
    public double Distance() => Math.Sqrt(X * X + Y * Y + Z * Z);
}
// Without 'readonly' on the struct, calling point.Distance() on an 'in' parameter
// forces the JIT to defensively copy 'point' first, in case Distance() mutates it.
// With 'readonly', the compiler proves it can't -- the copy is skipped entirely.

// Large Object Heap threshold -- objects >= 85,000 bytes bypass Gen0/1/2 entirely
byte[] largeBuffer = new byte[100_000];   // goes straight to the LOH, not Gen0

